"""Shared bilingual entry journey, using existing routes."""
ROLES = [
 ('reproduce','Reproduce from existing data','Choose a methodology profile, run VALUE 101 and compare it with the baseline Run of the same release and profile.','选择方法学口径，运行 VALUE 101，与同一版本、同一口径的基线 Run 比较。'),
 ('adapt','Add your new data','Copy a Study, map fields and units, then run a separate case.','复制 Study，映射字段与单位，再运行独立案例。'),
 ('modify','Edit a module','Change a supported module under the corrected profile and compare its results with the baseline.','在修正口径下修改支持的模块，与基线结果比较。'),
 ('extend','Add a new function to VALUE','Define inputs and outputs, add an extension and run a small example of two periods or longer under the corrected profile.','定义输入输出，接入扩展，在修正口径下运行两时段或更长的小型示例。')]

def paths(w):
 return '<div class="path-grid">'+''.join('<a class="path-card" href="'+w.url('community')+'#'+key+'"><span class="card-index">0'+str(i+1)+'</span><h3>'+label+'</h3><p>'+w.t(en,zh)+'</p></a>' for i,(key,label,en,zh) in enumerate(ROLES))+'</div>'

def name_explanation(w):
 full='Variable renewable electricity Allocation, Load-enabled excess-generation Utilisation, and system Evolution'
 return '<p class="small value-name">'+w.t('VALUE ('+full+').','VALUE（'+full+'）：可变可再生电力的分配、通过负荷利用富余发电，以及电力系统演化。')+'</p>'

def home(w):
 t=w.t
 edition=w.CONFIG.get("methodology_edition")
 metadata=''
 manifest=w.ROOT/'methodology/edition.json'
 if manifest.exists():
  import json
  info=json.loads(manifest.read_text())
  metadata='<p class="small">'+info['revision'][w.LANG]+' · '+info['basisLabel'][w.LANG]+'</p>'
 return '<section class="hero wrap"><div class="hero-copy">'+w.heading('VALUE <span class="value-full-name">Variable renewable electricity Allocation, Load-enabled excess-generation Utilisation, and system Evolution</span>',t('Electricity systems,<br>operating and evolving.','电力系统，<br>运行与演化。'),t('Connect half-hourly operation with annual investment decisions.','连接半小时运行与年度投资决策。'))+'<div class="actions">'+w.a('community','Get started','开始使用','button')+w.a('models/value','Explore the model','了解模型','button button-outline')+'</div></div>'+w.diagram()+'</section><section class="section wrap">'+w.section_head(t('CHOOSE YOUR TASK','选择你的任务'),t('Start with a small example.','从小型案例开始。'))+paths(w)+'</section><section class="section soft-band"><div class="wrap">'+w.cards([(t('Install','安装'),(t('VALUE 0.7.0-alpha.1 Full installers are available. Check platform validation before starting.','VALUE 0.7.0-alpha.1 的 Full 安装包可下载；开始前查看平台验收状态。') if w.CONFIG.get('publication_ready') else t('VALUE 0.7.0-alpha.1 Full packages: see platform verification and installation guidance.','VALUE 0.7.0-alpha.1 Full 安装包：查看平台验收与安装指南。')),w.a('docs/value','Installation guide','安装指南')),(t('Data','数据'),t('Begin with CC0 teaching inputs, then bring data with its own source and terms.','从 CC0 教学输入开始，再接入有来源与许可的数据。'),w.a('data','Find the inputs','获取输入')),(t('Methodology','方法学'),t('Read the equations, algorithms and inputs for your VALUE configuration.','阅读对应 VALUE 配置的公式、算法与输入。'),w.a('methodology','Read the methods','阅读方法'))])+metadata+'</div></section>'

def pages(w):
 t=w.t;out=[]
 for path in ['community','docs/value','docs']:
  title=desc=body=''
  if path=='community':
   title=t('Get started with VALUE','开始使用 VALUE');desc=t('Choose a task, then follow the matching workflow.','选择任务，再按对应流程操作。')
   body=w.heading(t('GET STARTED','开始使用'),title,desc)+paths(w)
   instructions=[['Install VALUE 0.7.0-alpha.1; the VALUE 101 teaching data is included.', 'In Studies, open or copy the teaching Study and choose its methodology in step 1; start the Run from Runs. The Run is listed at once and shows its preparation.', 'In Compare, select your Run and the baseline Run of the same release and methodology; every delta is measured against the Reference Run. If doctoral reproduction annual results are withheld, read them in Inspect or the ledger files.'], ['Copy a Study and its data pack.', 'Map the declared column, field names, units, time zone and sampling interval: demand is half-hourly or hourly, and the VALUE 101 demand values are read as MW, so map them as MW; optionally declare a timestamp column (UTC or Europe/London) and its date order, which are checked row by row; give EUR prices a rate, FX basis and price year; interconnector availability is positive for import and negative for export.', 'Check the three validation layers in the Data page panel, confirm in the Study editor that the pack is available for the chosen profile, then run a separate case.'], ['Under the corrected profile, choose a supported module and keep its baseline.', 'Change it in a separate copy and install it under a new identity (an in-place edit of an installed module is allowed and Runs record the new source hash); confirm the Study migration when the method changes.', 'Run the same short case and compare results; restore a disabled or quarantined module from Disabled and quarantined on the Modules page.'], ["Define the extension's input and output contract.", 'Implement and register it through the supported interface and return artifacts from the after_psm hook; a conflicting or broken extension is quarantined until you fix it and Rescan; API scripts send the session header and poll the Run they start.', 'Run a small example of two periods or longer under the corrected profile (the one-day lesson does not run extensions) before a longer study.']]
   chinese=[['安装 VALUE 0.7.0-alpha.1；VALUE 101 教学数据随包提供。', '在 Study 页打开或复制教学 Study，在第 1 步选择方法学口径；到 Run 页启动 Run，Run 立即列出并显示准备进度。', '在“比较”页选择你的 Run 与同一版本、同一口径的基线 Run，所有差值都相对“参照 Run”计算；论文复现口径的年度结果若暂不发布，在“检查”页或账本文件中查看。'], ['复制 Study 与数据包。', '映射声明的列、字段名、单位、时区和采样间隔：需求用半小时或逐时数据，VALUE 101 的需求数值按 MW 读取，改写时选 MW；可以声明时间戳列（UTC 或 Europe/London）和日期顺序，系统逐行检查；欧元价格要填汇率、汇率口径和价格年份；互联线可用量正值为进口、负值为出口。', '在 Data 页的校验面板查看三层校验，在 Study 编辑器确认数据包可用于所选口径，再运行独立案例。'], ['在修正口径下选择受支持的模块，并保留基线。', '在独立副本中修改，并以新身份安装；原地修改已安装的模块也可以，结果会记录新的源码哈希。属于方法变化时，要在界面确认 Study 迁移。', '运行相同的短案例并比较结果；停用或隔离的模块，在 Modules 页的 Disabled and quarantined 区恢复。'], ['定义扩展的输入输出契约。', '通过受支持的接口实现并登记，产物从 after_psm 钩子返回；冲突或损坏的扩展会被隔离，修复后点 Rescan；直接调用 API 的脚本要带会话头，并轮询异步启动的 Run。', '先在修正口径下用两时段或更长范围运行小型示例（一日课程不运行扩展），再开展长期研究。']]
   for i,(key,label,en,zh) in enumerate(ROLES):
    body+='<section class="page-section" id="'+key+'"><h2>'+label+'</h2><ol>'+''.join('<li>'+t(a,b)+'</li>' for a,b in zip(instructions[i],chinese[i]))+'</ol></section>'
   body+='<div class="actions">'+w.a('docs/value','Install VALUE','安装 VALUE','button')+w.a('data','Choose inputs','选择输入','button button-outline')+w.a('docs','Develop VALUE','开发 VALUE','button button-outline')+'</div>'
  elif path=='docs':
   title=t('Develop VALUE','开发 VALUE');desc=t('Adapt inputs, edit modules and add functions with a small reproducible case.','用小型可复现案例接入数据、修改模块与新增功能。')
   body=w.heading('VALUE / '+t('DEVELOP','开发'),title,desc)+w.cards([(label,t(en,zh),w.a('community#'+key,'Follow this workflow','查看对应流程')) for key,label,en,zh in ROLES[1:]])+'<p>'+w.external('https://github.com/hanzohanzhe/Value/tree/source-2026-10-09',t('Source repository · source-2026-10-09','源码仓库 · source-2026-10-09'))+'</p>'+w.note(t('Software and materials','软件与材料'),t('VALUE software uses Apache-2.0. Documentation uses CC BY 4.0; teaching data uses CC0; third-party terms remain separate. Research citation is recommended.','VALUE 软件采用 Apache-2.0，文档采用 CC BY 4.0，教学数据采用 CC0；第三方条款分别适用。建议在研究成果中引用项目。'))
  elif path=='docs/value':
   title=t('Install VALUE','安装 VALUE');desc=t('Download the VALUE 0.7.0-alpha.1 Full package for your platform, then follow these steps.','下载对应平台的 VALUE 0.7.0-alpha.1 Full 安装包，再按以下步骤操作。')
   body=w.heading('VALUE / '+t('INSTALL','安装'),title,desc)+'<ol class="checklist">'+''.join('<li>'+t(en,zh)+'</li>' for en,zh in [('Choose your platform and the matching Full package.','选择平台与对应 Full 安装包。'),('Extract the complete archive into a new directory.','将完整归档解压到新目录。'),('Run the platform installer into a directory that does not exist or is empty, launch VALUE, and keep its terminal open.','运行安装器，安装到不存在或为空的目录，启动 VALUE，并保持终端打开。'),('Open the address printed by the launcher (http://127.0.0.1:8800); the interface opens in English, and English / 中文 at the bottom of the sidebar switches the language. Start with VALUE 101.','打开启动器显示的地址（http://127.0.0.1:8800）。界面默认英文，可在侧栏底部用 English / 中文 切换。从 VALUE 101 开始。')])+'</ol><pre class="code-box">cd VALUE-Linux-x64\n./install-value --prefix "$HOME/VALUE-0.7.0"\n"$HOME/VALUE-0.7.0/start-value"</pre>'+w.note(t('Platform availability','平台状态'),t('VALUE 0.7.0-alpha.1 Full packages are available for download. Linux: offline installation and the VALUE 101 check passed for this release on 9 October 2026. Windows and macOS: experimental; native acceptance, signing and notarisation are planned for later releases.','VALUE 0.7.0-alpha.1 的 Full 安装包可下载。Linux：2026年10月9日本版本断网安装与 VALUE 101 检查通过。Windows、macOS：实验性；实机验收、签名与公证列入后续发布工作。'))+'<div class="actions">'+w.a('releases','Download status','下载状态','button')+w.a('community','Start your task','开始你的任务','button button-outline')+'</div>'
  if path=='docs/value':
   body+=w.note(t('Included environment','随包环境'),t('Full packages include Python, Node and the required dependencies. Start with the bundled environment.','Full 包包含 Python、Node 与所需依赖，直接使用随包环境。'))
   body+=w.note(t('Local use','本机使用'),t('One user per computer. Do not install VALUE on shared computers or remote-desktop servers.','一台电脑一个使用者，不要安装在共用电脑或远程桌面服务器上。'))
   body+=w.table([t('Platform','平台'),t('Install','安装'),t('Launch','启动')],[['Linux','<code>./install-value --prefix "$HOME/VALUE-0.7.0"</code>','<code>"$HOME/VALUE-0.7.0/start-value"</code>'],['Windows','<code>install-value.cmd</code>',t('Run start-value.cmd in the installed directory.','在安装目录运行 start-value.cmd。')],['macOS','<code>Install VALUE.command</code>',t('Open Start VALUE.command in the installed directory.','在安装目录打开 Start VALUE.command。')]])
   body+='<div class="faq"><h2>'+t('Common questions','常见问题')+'</h2>'+''.join('<details><summary>'+t(en,zh)+'</summary><p>'+t(a,b)+'</p></details>' for en,zh,a,b in [('Opening the local page', '打开本机页面的方法', 'Keep the launch terminal open and use the address it prints (http://127.0.0.1:8800 or http://localhost:8800). Every page has its own address, so a copied link reopens the same view.', '保持启动终端打开，使用它显示的地址（http://127.0.0.1:8800 或 http://localhost:8800）。每个页面有自己的网址，复制的链接会回到同一画面。'), ('How do I stop the application?', '如何停止应用？', 'Press Ctrl+C in the launch terminal. Runs whose model worker has started keep running in the background and are supervised again at the next start; a Run that is still being prepared stops and shows “Run preparation interrupted”, so start it again. Install new versions in a separate, empty directory.', '在启动终端按 Ctrl+C。已经启动模型 worker 的 Run 会在后台继续，下次启动时重新接管；还在准备阶段的 Run 会停止，下次显示 “Run preparation interrupted”，需要重新启动。新版本安装到另一个空目录。'), ('Inputs fail validation.', '输入校验失败。', 'Check field names, units, missing values and timestamps, the declared column and, for EUR prices, the rate, FX basis and price year. Demand needs at least one model year: 17,520 half-hourly values, or hourly rows (8,760 or 8,784), each hour being used for two half-hour periods. The VALUE 101 demand files are read as MW although their header says mwh, so map rewritten demand as MW; a demand whose annual energy differs from the replaced file by more than about 1.5 times gets a warning. Hourly prices and availability are each used for two half-hour periods. Save the file as comma-separated CSV. Any other series shorter than a model year is filled by repeating it from its start and needs your confirmation before it is committed. An optional timestamp column is checked row by row, with the date order detected or chosen. The Data page shows the three validation layers of each pack. Start with VALUE 101.', '检查字段、单位、缺失值、时间戳和声明的列；欧元价格还要填汇率、汇率口径和价格年份。需求至少覆盖一个模型年：半小时数据 17,520 个值，或逐时数据 8,760、8,784 行，每小时用于两个半小时。VALUE 101 的需求文件表头写 mwh，但按 MW 读取，改写需求时映射选 MW；新需求的年电量与被替换文件相差约 1.5 倍以上时会有警告。逐时的价格和可用量，每个值用于两个半小时。文件要存为逗号分隔的 CSV。需求以外的序列不满一个模型年时，从开头重复补齐，提交前要另行确认。可选的时间戳列会逐行检查，日期顺序可自动识别或手动选择。Data 页列出每个数据包的三层校验。先运行 VALUE 101。'), ('The page says ‘Open VALUE from its launcher’.', '页面显示 Open VALUE from its launcher。', 'The page was opened through another address, an old bookmark or another installation. Close it, start VALUE again with its launcher, then use http://127.0.0.1:8800 or http://localhost:8800.', '页面不是经启动器打开的（用了其他地址、旧书签或另一份安装）。关闭页面，用启动器重新启动 VALUE，再打开 http://127.0.0.1:8800 或 http://localhost:8800。'), ('A module or extension is quarantined (health: degraded).', '模块或扩展被隔离（health 显示 degraded）。', 'VALUE keeps running without it. Open Modules: the Disabled and quarantined area lists it with its manifest file and Enable, Rescan and Remove. Fix the code, then press Rescan (or Rescan modules at the top); Rescan also imports extension hooks again. If two manifests declare the same module ID, press Disable on either row: the copy is moved aside, then Enable restores the module. Remove moves the installation aside and is refused while a Study or Run uses it. Hook files of an installed extension may be edited in place, as for modules: Enable re-imports them and Runs record the new source hash; Enable is refused while a hook does not import. If you install, enable, disable or remove a module or extension while Runs are waiting, VALUE asks you to confirm: Runs that have not started are stopped, so resubmit them from the Runs page (Resubmit with current code) or start them again from the Study; Runs already running keep their code but cannot be resumed after the change. Offline: python -m gridform_core.module_recovery.', 'VALUE 会在没有它的情况下继续运行。打开 Modules 页，Disabled and quarantined 区列出该条目和它的清单文件，带 Enable、Rescan、Remove 三个按钮。修好代码后点 Rescan（或页头的 Rescan modules）；Rescan 也会重新导入扩展钩子。同一模块 ID 有两份清单时，在任一行点 Disable，副本会被移到一旁，之后点 Enable 恢复。Remove 只是把安装移到一旁；Study 或 Run 仍在使用时会被拒绝。已安装扩展的钩子文件与模块一样可以原地修改：Enable 会重新导入，Run 记录新的源码哈希；钩子无法导入时 Enable 会被拒绝。有 Run 在等待时安装、启用、停用或移除模块或扩展，VALUE 会请你确认：尚未开始的 Run 会被停下，可在 Runs 页点 Resubmit with current code 重新提交，或从 Study 重新启动；已在运行的 Run 保持原代码，但变更后不能再 Resume。离线时用 python -m gridform_core.module_recovery。'), ('Annual results withheld for this reproduction run.', '论文复现 Run 的年度结果被扣发。', 'The doctoral reproduction profile publishes annual results only when every raw invariant passed. While the Run is still going, the check is pending. The notice names the raw invariant that failed. Read the results in Inspect or open the ledger files.', '论文复现口径只有在原始不变量全部通过时才发布年度结果；Run 进行中显示待定。提示中写明失败的原始不变量。可以在 Inspect 中查看，或打开账本文件。'), ('The one-day lesson will not start with my extension.', '选了扩展后一日课程不能运行。', 'The one-day lesson runs the market step only, so extensions would not execute. Choose two-period or a longer scope, or deselect the extension.', '一日课程只运行市场步骤，扩展不会执行。请改用两时段或更长的范围，或取消选择扩展。'), ('The first Run takes several minutes to start.', '第一个 Run 要等几分钟才开始。', 'In a new data folder the first Run archives the Python runtime once (about 3 minutes). The Run is listed at once and shows its preparation step; other pages stay usable, and you can cancel it before its model worker starts. Until a comparable Run has finished, the runtime estimate is a range.', '在新数据目录中，第一个 Run 要先把 Python 运行环境归档一次（约 3 分钟）。Run 会立即列出并显示准备步骤；其他页面照常可用，模型 worker 启动之前可以取消。还没有可比的已完成 Run 时，运行时间估算给出一个区间。'), ('Why are replay times in UTC?', '为什么回放时间是 UTC？', 'VALUE runs on UTC half-hours of a fixed 365-day model year: 29 February is skipped in a leap year and there is no daylight-saving shift. Timestamps declared in Europe/London are converted to UTC when the file is mapped. Market replay and exports label times as UTC model time.', 'VALUE 的模型时钟是 UTC 半小时、固定 365 天的模型年：闰年跳过 2 月 29 日，没有夏令时切换。按 Europe/London 声明的时间戳在映射时换成 UTC。Market replay 和导出把时间标为 UTC model time。'), ('Why is Unserved demand larger than the unserved energy in the costs?', '为什么年度卡片的 Unserved demand 比成本中的切负荷大？', 'Unserved demand includes the stress shortfall: periods in which the accepted supply fell short of demand, recorded without changing dispatch or prices. The cost accounts value only the unserved energy recorded by the model, at £17,000/MWh. Both are removed from energy served, so the cost per MWh served and the carbon intensity use the energy actually delivered.', 'Unserved demand 包含 stress 缺口，即接纳的供给小于需求的时段；记录缺口时不改变调度和电价。成本账只按 17,000 £/MWh 给模型记录的切负荷计价。两者都从已供电量中扣除，所以每 MWh 供电成本和碳强度按实际交付的电量计算。'), ('How do I switch the interface to Chinese?', '如何把界面切换为中文？', 'Use English / 中文 at the bottom of the sidebar. English is the default; the choice is remembered in this browser and the page address does not change.', '在侧栏底部点 English / 中文。默认英文；选择保存在本浏览器中，网址不变。')])+'</div>'
  out.append((path,title,desc,body))
 return out
